package net.officefloor.hq.app.invoices;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * An invoice's number, made from its id: INV-, the id padded to six digits, then a Luhn check
 * digit over those six digits — so invoice 7 is INV-0000075.
 */
public final class InvoiceNumber {

    private static final Pattern FORM = Pattern.compile("INV-(\\d{6})(\\d)");

    private InvoiceNumber() {
    }

    /** The number of the invoice with this id. */
    public static String of(long id) {
        String digits = String.format("%06d", id);
        return "INV-" + digits + checkDigit(digits);
    }

    /**
     * The invoice id a typed number stands for. Empty when it is not of the form INV-nnnnnnn or its
     * check digit does not match — the number was mistyped.
     */
    public static Optional<Long> idOf(String typed) {
        Matcher m = FORM.matcher(typed.trim().toUpperCase());
        if (!m.matches() || checkDigit(m.group(1)) != m.group(2).charAt(0) - '0') {
            return Optional.empty();
        }
        return Optional.of(Long.parseLong(m.group(1)));
    }

    /**
     * Luhn: from the rightmost digit, double every second digit (the rightmost, the third from the
     * right, ...), subtracting 9 from any result over 9; the check digit brings the sum of all the
     * digits up to the next multiple of ten.
     */
    static int checkDigit(String digits) {
        int sum = 0;
        for (int i = 0; i < digits.length(); i++) {
            int d = digits.charAt(digits.length() - 1 - i) - '0';
            if (i % 2 == 0) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
        }
        return (10 - sum % 10) % 10;
    }
}
package net.officefloor.hq.app.invoices;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/** A payment received from a client on a date, allocated to its invoices. */
@Entity
@Table(name = "payment")
public class Payment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "client_id")
    private Long clientId;

    private BigDecimal amount;

    @Column(name = "payment_date")
    private LocalDate date;

    @ElementCollection
    @CollectionTable(name = "payment_allocation", joinColumns = @JoinColumn(name = "payment_id"))
    private List<PaymentAllocation> allocations = new ArrayList<>();

    protected Payment() {
    }

    /** A payment made wholly against one invoice. */
    public static Payment against(Invoice invoice, BigDecimal amount, LocalDate date) {
        Payment payment = new Payment();
        payment.clientId = invoice.getClientId();
        payment.amount = amount;
        payment.date = date;
        payment.allocations.add(new PaymentAllocation(invoice.getId(), amount));
        return payment;
    }

    public Long getId() {
        return id;
    }

    public Long getClientId() {
        return clientId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public List<PaymentAllocation> getAllocations() {
        return allocations;
    }

    /** How much of this payment goes to the invoice. */
    public BigDecimal amountTo(Long invoiceId) {
        return allocations.stream().filter(a -> a.getInvoiceId().equals(invoiceId))
                .map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
